SELECT CAST(COUNT(DISTINCT CASE WHEN a.dischtime IS NOT NULL AND a.dischtime <= a.admittime + INTERVAL '30 days' THEN a.subject_id END) AS FLOAT) / NULLIF(COUNT(DISTINCT a.subject_id), 0) AS readmission_rate, AVG(a.los) AS avg_los, SUM(CASE WHEN a.los > 9 THEN 1 ELSE 0 END) * 100.0 / NULLIF(COUNT(DISTINCT a.subject_id), 0) AS percent_los_gt_9_days FROM admissions a JOIN patients p ON a.subject_id = p.subject_id WHERE p.gender = 'M' AND EXTRACT(YEAR FROM age(CURRENT_DATE, p.dob)) = 70 AND p.insurance = 'Medicare' AND EXTRACT(YEAR FROM a.admittime) BETWEEN 2015 AND 2016 AND a.admission_type = 'ED' AND a.principal_diagnosis = 'acute respiratory failure' GROUP BY a.subject_id HAVING COUNT(DISTINCT a.dischtime) > 0;